def control(obs):
    v = obs['motion']['v_mps']
    t = obs['t']
    if S['phase'] == 'fwd':
        if S['t0'] is None and v > 0.3:
            S['t0'] = t
        if S['t0'] is None or t - S['t0'] < 2.0:
            return {'steer_deg': -12.0, 'speed_mps': 0.6, 'look_deg': 0}
        S['phase'] = 'rev'
    h = obs['hitch_deg']
    y = obs['rig']['trailer_rear'][1]
    steer = 4.0 * h + 15.0 * (y + 0.15)
    steer = max(-34.0, min(34.0, steer))
    return {'steer_deg': steer, 'speed_mps': -0.8, 'look_deg': -23}

